676	function SuggestionField({
677	  label,
678	  current,
679	  proposed,
680	  checked,
681	  onToggle,
682	}: {
683	  label: string;
684	  current: string;
685	  proposed?: string;
686	  checked: boolean;
687	  onToggle: () => void;
688	}) {
689	  if (!proposed) {
690	    return (
691	      <div className="space-y-1">
692	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
693	        <p className="text-xs text-muted-foreground italic">No change suggested.</p>
694	      </div>
695	    );
696	  }
697	  if (proposed === current) {
698	    return (
699	      <div className="space-y-1">
700	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
701	        <p className="text-xs text-muted-foreground italic">No change — AI returned the same value.</p>
702	      </div>
703	    );
704	  }
705	  return (
706	    <div className="space-y-1.5">
707	      <div className="flex items-center justify-between">
708	        <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">{label}</p>
709	        <label className="flex items-center gap-1.5 text-[11px] text-muted-foreground cursor-pointer select-none">
710	          <input
711	            type="checkbox"
712	            checked={checked}
713	            onChange={onToggle}
714	            className="h-3 w-3 accent-primary"
715	          />
716	          Apply this
717	        </label>
718	      </div>
719	      {current && (
720	        <p className="text-xs text-muted-foreground/70 line-through bg-background/40 border border-border rounded px-2 py-1">
721	          {current}
722	        </p>
723	      )}
724	      <p className={`text-xs leading-relaxed bg-background/60 border rounded px-2 py-1.5 ${checked ? "text-foreground border-primary/40" : "text-muted-foreground border-border"}`}>
725	        {proposed}
726	      </p>
727	    </div>
728	  );
729	}
