479	// ─── Entity Card ──────────────────────────────────────────────────────────────
480	
481	function EntityCard({
482	  entity, projectId, isExpanded, onToggle, onDelete, onUpdated,
483	  childEntities, isDeck, deckOptions,
484	}: {
485	  entity: Entity;
486	  projectId: number;
487	  isExpanded: boolean;
488	  onToggle: () => void;
489	  onDelete: () => void;
490	  onUpdated: () => void;
491	  childEntities?: Entity[];
492	  isDeck?: boolean;
493	  deckOptions?: Entity[];
494	}) {
495	  const queryClient = useQueryClient();
496	  const updateEntity = useUpdateEntity();
497	  const createEntity = useCreateEntity();
498	  const enhanceEntity = useAiEnhanceEntity();
499	  const { toast } = useToast();
500	
501	  const [showEnhance, setShowEnhance] = useState(false);
502	  const [isEnhancing, setIsEnhancing] = useState(false);
503	  const [enhance, setEnhance] = useState<AIEnhance | null>(null);
504	  const [selectedProps, setSelectedProps] = useState<Set<number>>(new Set());
505	  const [applying, setApplying] = useState(false);
506	  const [applied, setApplied] = useState(false);
507	
508	  const [isEditing, setIsEditing] = useState(false);
509	  const [editForm, setEditForm] = useState({
510	    name: entity.name,
511	    type: entity.type,
512	    subtype: entity.subtype ?? "",
513	    description: entity.description ?? "",
514	    parentEntityId: entity.parentEntityId ?? undefined as number | undefined,
515	  });
516	
517	  const createProperty = useCreateEntityProperty();
518	  const meta = getMeta(entity.type);
519	  const errMsg = (err: unknown) => err instanceof Error ? err.message : String(err);
520	
521	  const handleSaveEdit = async () => {
522	    try {
523	      await updateEntity.mutateAsync({
524	        projectId, entityId: entity.id,
525	        data: {
526	          name: editForm.name,
527	          type: editForm.type,
528	          subtype: editForm.subtype || undefined,
529	          description: editForm.description,
530	          parentEntityId: editForm.parentEntityId ?? null,
531	        },
532	      });
533	      setIsEditing(false);
534	      onUpdated();
535	      toast({ title: "Component updated" });
536	    } catch (err) {
537	      toast({ title: "Update failed", description: errMsg(err), variant: "destructive" });
538	    }
539	  };
540	
541	  const handleDuplicate = async () => {
542	    try {
543	      await createEntity.mutateAsync({
544	        projectId,
545	        data: { name: `${entity.name} (Copy)`, type: entity.type, description: entity.description ?? "" },
546	      });
547	      onUpdated();
548	      toast({ title: "Component duplicated" });
549	    } catch (err) {
550	      toast({ title: "Duplicate failed", description: errMsg(err), variant: "destructive" });
551	    }
552	  };
553	
554	  const handleEnhance = async () => {
555	    setIsEnhancing(true); setEnhance(null); setShowEnhance(true);
556	    try {
557	      const raw = await enhanceEntity.mutateAsync({ projectId, entityId: entity.id });
558	      const safeProps = Array.isArray(raw?.suggestedProperties)
559	        ? raw.suggestedProperties.filter((p): p is AIEnhance["suggestedProperties"][number] =>
560	            !!p && typeof p === "object" && typeof p.name === "string")
561	        : [];
562	      const data: AIEnhance = {
563	        description: typeof raw?.description === "string" ? raw.description : "",
564	        lore: typeof raw?.lore === "string" ? raw.lore : undefined,
565	        designNotes: typeof raw?.designNotes === "string" ? raw.designNotes : undefined,
566	        suggestedProperties: safeProps,
567	      };
568	      if (!data.description && data.suggestedProperties.length === 0) {
569	        toast({ title: "AI returned no usable suggestions", variant: "destructive" });
570	        setShowEnhance(false);
571	      } else {
572	        setEnhance(data);
573	        setSelectedProps(new Set(data.suggestedProperties.map((_, i) => i)));
574	      }
575	    } catch (err) {
576	      toast({ title: "AI enhance failed", description: errMsg(err), variant: "destructive" });
577	      setShowEnhance(false);
578	    } finally {
579	      setIsEnhancing(false);
580	    }
581	  };
582	
583	  const buildPropertyPayload = (p: { name: string; dataType: string; defaultValue?: string }) => {
584	    const payload: { name: string; dataType: string; defaultValue?: number; textValue?: string } =
585	      { name: p.name, dataType: p.dataType };
586	    if (p.defaultValue != null && p.defaultValue !== "") {
587	      const numeric = Number(p.defaultValue);
588	      if (Number.isFinite(numeric) && p.defaultValue.trim() !== "") payload.defaultValue = numeric;
589	      else payload.textValue = p.defaultValue;
590	    }
591	    return payload;
592	  };
593	
594	  const handleApply = async () => {
595	    if (!enhance) return;
596	    setApplying(true);
597	    try {
598	      await updateEntity.mutateAsync({
599	        projectId, entityId: entity.id,
600	        data: {
601	          description: enhance.description,
602	          ...(enhance.lore ? { lore: enhance.lore } : {}),
603	          ...(enhance.designNotes ? { designNotes: enhance.designNotes } : {}),
604	        },
605	      });
606	      const propsToAdd = enhance.suggestedProperties.filter((_, i) => selectedProps.has(i));
607	      for (const prop of propsToAdd) {
608	        await createProperty.mutateAsync({ projectId, entityId: entity.id, data: buildPropertyPayload(prop) });
609	      }
610	      queryClient.invalidateQueries({ queryKey: getListEntityPropertiesQueryKey(projectId, entity.id) });
611	      onUpdated();
612	      setApplied(true);
613	      toast({ title: "Applied!", description: `Description updated${propsToAdd.length ? ` + ${propsToAdd.length} propert${propsToAdd.length === 1 ? "y" : "ies"} added.` : "."}` });
614	      setTimeout(() => { setShowEnhance(false); setApplied(false); setEnhance(null); }, 1500);
615	    } catch (err) {
616	      toast({ title: "Apply failed", description: errMsg(err), variant: "destructive" });
617	    } finally {
618	      setApplying(false);
619	    }
620	  };
621	
622	  return (
623	    <Card className="bg-card border-border overflow-hidden transition-shadow hover:shadow-md hover:shadow-black/20 rounded-none border-0 border-b last:border-b-0">
624	      {/* Header or inline edit */}
625	      {isEditing ? (
626	        <div className="px-4 py-3 space-y-3 border-b border-border bg-muted/10">
627	          <div className="flex items-center gap-2 flex-wrap">
628	            <Input value={editForm.name}
629	              onChange={(e) => setEditForm((f) => ({ ...f, name: e.target.value }))}
630	              className="bg-input h-8 text-sm font-semibold flex-1 min-w-[140px]" autoFocus />
631	            <Select value={editForm.type}
632	              onValueChange={(v) => setEditForm((f) => ({ ...f, type: v, subtype: "" }))}
633	            >
634	              <SelectTrigger className="bg-input h-8 text-xs w-40"><SelectValue /></SelectTrigger>
635	              <SelectContent>
636	                <SelectGroup>
637	                  <SelectLabel className="text-[10px]">Physical</SelectLabel>
638	                  {PHYSICAL_TYPES.map((t) => <SelectItem key={t} value={t}>{getMeta(t).icon} {t}</SelectItem>)}
639	                </SelectGroup>
640	                <SelectGroup>
641	                  <SelectLabel className="text-[10px]">World</SelectLabel>
642	                  {WORLD_TYPES.map((t) => <SelectItem key={t} value={t}>{getMeta(t).icon} {t}</SelectItem>)}
643	                </SelectGroup>
644	              </SelectContent>
645	            </Select>
646	            <Select value={editForm.subtype || "__none__"}
647	              onValueChange={(v) => setEditForm((f) => ({ ...f, subtype: v === "__none__" ? "" : v }))}
648	            >
649	              <SelectTrigger className="bg-input h-8 text-xs w-36"><SelectValue placeholder="Subtype…" /></SelectTrigger>
650	              <SelectContent>
651	                <SelectItem value="__none__">— None —</SelectItem>
652	                {COMPONENT_SUBTYPES[editForm.type as ComponentType]?.map((s) => (
653	                  <SelectItem key={s} value={s}>{s}</SelectItem>
654	                ))}
655	              </SelectContent>
656	            </Select>
657	          </div>
658	          {editForm.type === "Card" && deckOptions && deckOptions.length > 0 && (
659	            <div className="space-y-1">
660	              <Label className="text-xs">Deck</Label>
661	              <Select
662	                value={editForm.parentEntityId ? String(editForm.parentEntityId) : "__none__"}
663	                onValueChange={(v) => setEditForm((f) => ({ ...f, parentEntityId: v === "__none__" ? undefined : parseInt(v) }))}
664	              >
665	                <SelectTrigger className="h-8 bg-input text-xs w-56"><SelectValue placeholder="No deck…" /></SelectTrigger>
666	                <SelectContent>
667	                  <SelectItem value="__none__">— No deck —</SelectItem>
668	                  {deckOptions.map((d) => <SelectItem key={d.id} value={String(d.id)}>📦 {d.name}</SelectItem>)}
669	                </SelectContent>
670	              </Select>
671	            </div>
672	          )}
673	          <Textarea value={editForm.description}
674	            onChange={(e) => setEditForm((f) => ({ ...f, description: e.target.value }))}
675	            placeholder="Description…" className="bg-input text-sm resize-none h-16" />
676	          <div className="flex gap-2">
677	            <Button size="sm" onClick={handleSaveEdit} className="h-7 text-xs bg-primary text-primary-foreground gap-1" disabled={updateEntity.isPending}>
678	              {updateEntity.isPending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Check className="w-3 h-3" />}Save
679	            </Button>
680	            <Button size="sm" variant="ghost"
681	              onClick={() => { setEditForm({ name: entity.name, type: entity.type, subtype: entity.subtype ?? "", description: entity.description ?? "", parentEntityId: entity.parentEntityId ?? undefined }); setIsEditing(false); }}
682	              className="h-7 text-xs text-muted-foreground hover:text-white"
683	            >
684	              <X className="w-3 h-3" />
685	            </Button>
686	          </div>
687	        </div>
688	      ) : (
689	        <div className="flex items-center justify-between px-4 py-3 cursor-pointer hover:bg-muted/10 transition-colors"
690	          onClick={onToggle} data-testid={`entity-row-${entity.id}`}
691	        >
692	          <div className="flex items-center gap-3 min-w-0 flex-1">
693	            {isExpanded
694	              ? <ChevronDown className="w-4 h-4 text-muted-foreground shrink-0" />
695	              : <ChevronRight className="w-4 h-4 text-muted-foreground shrink-0" />}
696	            <span className="text-sm shrink-0">{meta.icon}</span>
697	            <span className={`text-base font-semibold truncate ${meta.color}`}>{entity.name}</span>
698	            {entity.subtype && (
699	              <Badge variant="outline" className={`text-[10px] shrink-0 ${meta.badge}`}>{entity.subtype}</Badge>
700	            )}
701	            {/* Deck child count badge */}
702	            {isDeck && childEntities && childEntities.length > 0 && (
703	              <Badge variant="outline" className="text-[10px] shrink-0 bg-indigo-500/10 text-indigo-400 border-indigo-500/30">
704	                {childEntities.length} card{childEntities.length !== 1 ? "s" : ""}
705	              </Badge>
706	            )}
707	            {entity.description && (
708	              <span className="text-xs text-muted-foreground truncate hidden md:block">{entity.description}</span>
709	            )}
